        "id": "uploadOperationDocument",
        "value": "=if operation.operation_document_documentSource = \"camunda\" then operation.operation_document_camundaReference else if operation.operation_document_documentSource = \"inline\" then { \"camunda.document.type\": \"inline\", content: operation.operation_document_inline_content, name: operation.operation_document_inline_fileName, contentType: operation.operation_document_inline_contentType } else if operation.operation_document_documentSource = \"external\" then { \"camunda.document.type\": \"external\", url: operation.operation_document_external_url, name: operation.operation_document_external_fileName } else null",
