        "description": "Expected value of the JWT 'aud' claim",
        "optional": false,
        "constraints": {
          "notEmpty": true
        },
        "feel": "optional",
        "binding": {
          "name": "inbound.auth.jwt.audience",
          "type": "zeebe:property"
        },
        "condition": {
          "property": "inbound.auth.type",
          "equals": "JWT",
          "type": "simple"
        },
        "type": "String"
